import{_ as e,c as r,o as p,af as h}from"./chunks/framework.BKeRpnBD.js";const b=JSON.parse('{"title":"離","description":"高岛易断 - 離","frontmatter":{"title":"離","description":"高岛易断 - 離"},"headers":[],"relativePath":"zh/classics/takashima/030.md","filePath":"zh/classics/takashima/030.md"}'),i={name:"zh/classics/takashima/030.md"};function l(n,a,d,t,s,c){return p(),r("div",null,[...a[0]||(a[0]=[h('<h1 id="離" tabindex="-1">離 <a class="header-anchor" href="#離" aria-label="Permalink to “離”">​</a></h1><h2 id="離-1" tabindex="-1">離 <a class="header-anchor" href="#離-1" aria-label="Permalink to “離”">​</a></h2><h2 id="卦辞" tabindex="-1">卦辞 <a class="header-anchor" href="#卦辞" aria-label="Permalink to “卦辞”">​</a></h2><p>离：利贞，亨。畜牝牛吉。</p><h2 id="卦辞注" tabindex="-1">卦辞注 <a class="header-anchor" href="#卦辞注" aria-label="Permalink to “卦辞注”">​</a></h2><p>《坤》二成《离》，阴虚内合，卦体主柔；柔则近于不正，不正则不亨通，故利在行正，乃得亨通，是以“亨”在“利贞”之下也。按，他卦皆言“亨利贞”，《离》独先言“利贞”，而后“亨”，盖《离》内柔外刚，不得其正，始虽通，终必塞矣，故利在贞，贞而后乃亨也。“畜牝牛吉”者，《离》为《坤》之子，《坤》为牛，《离》亦为牝牛，牝牛柔顺，得《坤》之性。六爻阴为牝，二五在中，以阳包阴为畜。牝牛不中牺牲之用，利在孳生，故曰“畜”。《离》由《坤》二成，《坤》曰“牝马”，牝马利在行远，故取其贞；《离》曰“牝牛”，牝牛利在生息，故不取其贞也。《坤》资生，《离》为火，火生土，牛土性也，有生息不已之象，故曰“畜牝牛吉”。</p><h2 id="象辞" tabindex="-1">象辞 <a class="header-anchor" href="#象辞" aria-label="Permalink to “象辞”">​</a></h2><p>明两作，离。大人以继明照乎四方。</p><h2 id="象辞注" tabindex="-1">象辞注 <a class="header-anchor" href="#象辞注" aria-label="Permalink to “象辞注”">​</a></h2><p>“明两作”者，内外两《离》之象。《离》者日也，然不曰日而曰“明”者，以天无二日也。《离》者六画，重《离》之象。日月之明，终古不忒，大人之明，四方毕照，辨忠邪，知疾苦，烛幽侧，处久长。大人以德言，乃王公之称，有与天地合德，与日月合明者也。“继明”云者，内卦之《离》，继以外卦之《离》，即“明两作，离”之义也。明之功不继，则有时而昏，故必如《大学》之称“明明德”，《汤盘》之云“日日新”，可以向明出治，光被四方也。</p><h2 id="占断" tabindex="-1">占断 <a class="header-anchor" href="#占断" aria-label="Permalink to “占断”">​</a></h2><p>○　问战征：克敌者宜用火攻，防敌者亦宜备火攻，“两作”者，恐前后一时俱焚。</p><p>○　问营商：想营业定是近火，或运办硫黄，或创设电火，或制造火柴等业，皆利。</p><p>○　问功名：《离》为目，可有榜眼之兆。</p><p>○　问家宅：此屋必系新造，前后开通，窗户生明，屋外四围空阔，是巨室贵人之宅也，吉。</p><p>○　问婚姻：此非原配，必是继妻；夫家定属贵室，非寻常百姓之偶也。</p><p>○　问六甲：生女。</p><p>○　问疾病：热势甚重，恐一两日内即防神魂离散。</p><h2 id="初九解" tabindex="-1">初九解 <a class="header-anchor" href="#初九解" aria-label="Permalink to “初九解”">​</a></h2><p>初爻为内卦之始，如日之始出，黎明乍起，为作事谋始之时也。“履”，践履也，“错然”者，谓应酬交错也。当至纷至叠来，而不以敬将之，必致动辄得咎矣。《履》卦曰“履虎尾”，履而知惧，故曰“吉”；此卦曰“履错然”，履而能敬，故“无咎”，其履同也。夫祸福每兆于几微，始而能谨，斯终必无祸，所谓君子敬而无失，得者得此旨也。《象》曰“履错之敬，以避咎也”，夫人以身接物，不必居功，最宜避咎，避之之道，惟在居敬而已矣。</p><h2 id="初九占" tabindex="-1">初九占 <a class="header-anchor" href="#初九占" aria-label="Permalink to “初九占”">​</a></h2><p>○　问战征：初爻为始，是三军始行，旗辙交错之时也。“敬”者，即所谓临事而惧之意。战，危事也，慎重持之，或可免咎也。或曰邪行谓错，宜从横路进兵。</p><p>○　问商业：必是新立之业。初九爻辰在子，北方属水，卦位居南属火，想是南北生意。一时难许大利，要可无咎。</p><p>○　问功名：《诗》云“他山之石，可以攻玉”，盖言得助而成也。</p><p>○　问家宅：《履》卦云，“履道坦坦，幽人贞吉”，是宅必在大道之旁。吉。</p><p>○　问六甲：生女。</p><h2 id="初九案例" tabindex="-1">初九案例 <a class="header-anchor" href="#初九案例" aria-label="Permalink to “初九案例”">​</a></h2><p>友人某来请占气运，筮得《离》之《旅》。</p><p>断曰：《离》者，火也，火之性炎炎而上，其功在明，其用足以取暖，又足以烹调，是人世不可一日无者也。以人身配之，火为心魂，有心魂乃有知觉，有知觉乃可谋为万事。今占得初爻，知必为谋事伊始。然火之为功甚大，火之为祸亦甚烈，当其始燃，最宜谨慎小心，苟一不慎，初与四应，延及四爻，则“突如其来”，咎莫大焉，故戒之曰“敬之无咎”。足下占得此爻，宜知所畏惧焉。凡爻象一爻为一年，三年后正当四爻，尤宜谨慎，至四年则吉。</p><h2 id="六二解" tabindex="-1">六二解 <a class="header-anchor" href="#六二解" aria-label="Permalink to “六二解”">​</a></h2><p>二爻以阴居阴，为《坤》二成卦之主，位处中正，《彖传》所谓“柔丽于中正”者，即指二爻也。《离》为黄，故曰“黄离”，黄者中色，《离》者文明，居中而处文明，是以“元吉”也。《象》曰“得中道也”，《离》卦六爻，惟二爻以一柔居二刚之中，中而且正，《象》曰“得中”，不言正而正在是焉。</p><h2 id="六二占" tabindex="-1">六二占 <a class="header-anchor" href="#六二占" aria-label="Permalink to “六二占”">​</a></h2><p>○　问战征：《离》二变《大有》，《大有》，《象传》曰“大车以载，积中不败也”。“大车”，谓兵车；黄，中之色也；“积中”者，谓中营军粮充实；“不败”者，谓兵士勇健，得以获胜也。故吉。</p><p>○　问营商：《离》属南方之卦，经营利在南方；黄为土，土生木，又利在土木。</p><p>○　问功名：《离》位在午，上值文昌，有文明之象，功名必显。</p><p>○　问家宅：《离》为火，土色黄，火之子，喻言其家得有令子，能振起家声。吉。</p><p>○　问婚姻：二爻以阴居阴，位得中正，主夫妇顺从，佳偶也。吉。</p><p>○　问疾病：必是内火郁结中焦之症，宜凉解之。无咎。</p><p>○　问六甲：生女。</p><h2 id="六二案例" tabindex="-1">六二案例 <a class="header-anchor" href="#六二案例" aria-label="Permalink to “六二案例”">​</a></h2><p>某来请占某贵显，筮得《离》之《大有》。</p><p>断曰：《离》为火，又为日，得其柔暖之气，自足嘘枯回生，有煦育万物之象。今占得六二，二爻与五相应，五为尊位，知某贵显辅翼至尊，君臣合德。《离》有文明之德，黄属中央之色，知必能握中图治，化启文明也，故曰“黄离元吉”。</p><h2 id="九三解" tabindex="-1">九三解 <a class="header-anchor" href="#九三解" aria-label="Permalink to “九三解”">​</a></h2><p>九三以阳处阳，是由明入晦之象，故曰“日昃”，昃者，日之将倾也。“缶”，即盎，大腹而敛口，《离》卦上下奇而中偶，形似缶，故象取缶。《坎》曰“用缶”，《坎》中实，则用以盛酒；《离》中虚，则鼓以节乐。“不鼓缶而歌”，必歌无节也。《离》互《兑》，《兑》属正西，日出东入西，日薄西山，谓衰年暮景，故象取“大耋”。八十曰耋，三爻居二卦之中，犹年在半百，未可云大耋也。“嗟”，悲叹声，谓未老而叹其老也。其歌也，乐失其节，其嗟也，哀失其常，哀乐无时，致神魂颠倒，寿命不永矣，是以凶也。《象传》曰“何可久也”，谓若此之人，忽歌忽嗟，乃天夺其魄也，安能久乎？</p><h2 id="九三占" tabindex="-1">九三占 <a class="header-anchor" href="#九三占" aria-label="Permalink to “九三占”">​</a></h2><p>○　问战征：“日昃”，日将夕也。军中长歌浩叹，皆失纪律，不吉之兆，尤防敌兵夜袭。</p><p>○　问营商：《周礼》地官司市，“大市日昃而市”，谓大市交易繁多，至日昃始集市。爻曰“日昃之离”，是日昃后而散也。市区扰杂，或歌或嗟，哀乐无度，必伤正业，宜戒。</p><p>○　问功名：恐老大无成，徒自悲耳。</p><p>○　问婚姻：鼓缶而歌，难望偕老，凶。</p><p>○　问六甲：生女，难育。</p><h2 id="九三案例" tabindex="-1">九三案例 <a class="header-anchor" href="#九三案例" aria-label="Permalink to “九三案例”">​</a></h2><p>友人某来曰：余将娶某女，请占吉凶。筮得《离》之《噬嗑》。</p><p>断曰：爻辞曰，“日昃之离”，《离》，离散也，“日昃之离”，谓婚后而复离也。“鼓缶而歌”，惮亡也；不鼓而歌，非惮亡，必生离，“大耋之嗟”，是叹其不得偕老也。此婚不成为上，成则亦必离散，不吉之兆。后友人不信此占，媒娶成婚，未几因家门不和，又复离散，果如所占云云。</p><p>明治三十年，占我国与法国交际，筮得《离》之《噬嗑》。</p><p>断曰：《离》为甲，为刀，为矢，皆主战兵器也；《离》亦为火，又足备火炮之用。今占法国交际，而得三爻，是令我急备兵甲战具也。爻辞曰“日昃之离”，“日昃”者，日将西倾，可见西土运旺之时。“不鼓缶而歌，则大耋之嗟”，谓不当歌而歌，不当嗟而嗟，犹言措置失时也。善谋国者，当及时修备，固不可自耽安逸，亦不必自示衰弱。睦邻修好，以保永图，斯为善也。</p><h2 id="九四解" tabindex="-1">九四解 <a class="header-anchor" href="#九四解" aria-label="Permalink to “九四解”">​</a></h2><p>“突如其来如”者，谓刚暴之祸，不可测度；“焚如”者，谓如烈火之焚物；“死如，弃如”者，谓其身灭亡，其名亦遂废弃。四爻处上下卦之间，下卦之火将熄，上卦之火又炽，火炎于上，其势尤烈。“突”，杨子《方言》，“江湘人谓卒相见曰突”，“突如其来”，是骤来而不及防也。“焚如”，烧其庐；“死如”，毁其身；“弃如”，举之而委诸沟壑也。“焚如”，《离》火本象；四动体《艮》，《艮》为鬼冥门，故曰“死如”；又互《兑》，《兑》刑人，刑人于市，与个弃之，故曰“弃如”。焚而死，死而弃，其势相连，其祸甚凶，以九四在三火相传之际，是以凶焰如此。《象传》曰“无所容也”，谓火焰逼近，无可容身也。四与初应，初之火其咎可避，四之火猛，屋毁人亡，无地可容矣。或曰突谓灶突，《汉书》所云“其灶直突”之突。“突如其来”者，所谓祭神如神在，恍惚而见其来也。“焚如，弃如”者，谓灶神察其为恶，而降兹凶也。此又一说也。</p><h2 id="九四占" tabindex="-1">九四占 <a class="header-anchor" href="#九四占" aria-label="Permalink to “九四占”">​</a></h2><p>○　问战征：有营垒被焚，枪炮暴烈之祸，来势汹涌，紧官慎防。</p><p>○　问营商：有人财两亡之祸，宜藏身退避，或可免也。</p><p>○　问功名：有唾手可得之势，但位名愈重，得祸尤烈，不如隐退。</p><p>○　问家宅：旧说以“突”为不孝子，此家必生逆子。“焚”、“死”、“弃”，皆言逆子之罪也。</p><p>○　问婚姻：四动体《艮》，《艮》为鬼冥门，又《离》互《兑》，《兑》为刑人，此婚大不吉利。</p><p>○　问六甲：生女，必不育。</p><h2 id="九四案例" tabindex="-1">九四案例 <a class="header-anchor" href="#九四案例" aria-label="Permalink to “九四案例”">​</a></h2><p>明治二十三年春，友人某来，请占本年气运。</p><p>断曰：九四在上下二火之间，下火将熄，上火复燃，火炎上，故《离》卦以四爻为最凶。今占气运，而得四爻，四爻以阳处阴，外刚内柔，位不中正。主有阴险邪僻之徒，拨弄其间。初若不觉，及其势焰一炽，“突如其来”，不特祸延家室，而身肌发肤，并受其殃，如火之燎原，有不可扑灭者矣，谓之“焚如，死如，弃如”。足下宜谨防小人，毋为饲犬而啮手也。某氏素性柔弱，不甚介意，委用亲族少年，不料妄作妄为，既凶且毒，某氏家产，因人倾败，祸又未已，某氏始为悔悟，亦已晚矣。</p><h2 id="六五解" tabindex="-1">六五解 <a class="header-anchor" href="#六五解" aria-label="Permalink to “六五解”">​</a></h2><p>六五为外卦之主，得中居尊，与二相应，《象传》所谓大人继明久照，即指五爻也。《离》为目，自目出者曰涕，故曰“出涕沱若”。又《离》互《兑》为口，嗟是口之喑声，故曰“戚嗟若”。所谓“若”者，是未当“出涕”而有若“出涕”，未当“戚嗟”而有若“戚嗟”，盖形容忧伤之情状也。九三乐尽悲来，“大耋之嗟”，则为凶兆。九五忧盛虑危，所谓“先天下之忧而忧，后天下之乐而乐”，故吉。《象传》曰“《离》五公也”，九五为王公之位，故云。</p><h2 id="六五占" tabindex="-1">六五占 <a class="header-anchor" href="#六五占" aria-label="Permalink to “六五占”">​</a></h2><p>○　问战征：据爻辞“沱若”“嗟若”，有临事而惧之意。战危事也，能惧则能谋，能谋则可以制胜矣，故吉。</p><p>○　问营商：此经营必是王家商务公业，非下民私计也。故曰“离王公也”。其业亦必由辛苦艰难而成。</p><p>○　问功名：位至宰辅，极贵极显，然一身忧劳倍甚，如武侯之鞠躬尽瘁，乃吉。</p><p>○　问婚姻：此姻事极贵，然有先号咷而后笑之象。</p><p>○　问六甲：生女，防难产，终吉。</p><h2 id="六五案例" tabindex="-1">六五案例 <a class="header-anchor" href="#六五案例" aria-label="Permalink to “六五案例”">​</a></h2><p>占某豪商时运，筮得《离》之《同人》。</p><p>断曰：五居尊位，在国为一国之君，在家为一家之主，在乡为一乡之望也。爻辞所云“出涕沱若，戚嗟若”，谓能先事预谋，防危虑盛，百计图维，以期万全者，此非老成练达者不能也。足下占得此爻，可知足下历尝艰苦，在平时悲泣号叹之状，不知若何哀切者；亦由此继明之德，足以察识事机，而能保守家业，不为亲族少年所得欺瞒也。故吉。</p><h2 id="上九解" tabindex="-1">上九解 <a class="header-anchor" href="#上九解" aria-label="Permalink to “上九解”">​</a></h2><p>“王”者指六五，“用者”，指上九也。《离》为兵戈，故用以“出征”。“首”者首恶，“丑”者类也。“嘉”者，赏其功也；所嘉者，在折其魁首，而不及丑类，《书》所谓“歼厥渠魁，胁从罔治”者是也。九三居下卦之上，与上为敌，不顺王化，残害民生，上九于是奉命出师，以除天下之害，获其首恶，诛而戮之，其余党类，皆从赦免。此诚吊民伐罪，王者之师，复何咎焉！《象传》曰：“以正邦也”，谓如汤之征葛伯，文王之伐昆夷，惟在戡乱以安邦，夫岂好为穷兵哉！</p><h2 id="上九占" tabindex="-1">上九占 <a class="header-anchor" href="#上九占" aria-label="Permalink to “上九占”">​</a></h2><p>○　问战征：观爻辞已明示矣。王者之师，不妄杀人，斯道得焉矣。</p><p>○　问营商：贩售货物，宜选取上等佳品，不取低劣，乃可获利。</p><p>○　问功名：必膺首选，吉。</p><p>○　问疾病：“折”，夭折也，不利。</p><p>○　问六甲：生女。</p><h2 id="上九案例" tabindex="-1">上九案例 <a class="header-anchor" href="#上九案例" aria-label="Permalink to “上九案例”">​</a></h2><p>明治七年三月，佐贺乱，朝廷将发师征讨，有陆军大佐某，同中佐某来，谓曰：今将出师，请为一占。筮得《离》之《丰》。</p><p>断曰：爻辞所云“王用出征”，适合今日之事也。在佐贺乱党兴叛，其中必有主谋，即所谓“魁首”，是乃乱之首，罪之魁也，罪在不赦；一时响应而起，皆胁从之徒，是丑类也。今以佐贺启叛，命师往征，在我皇上神机庙算，素以不嗜杀人为心，必将布告天下，谓构兵倡乱，罪在一人，寡人誓必取而戮之，余无所问，有能擒获渠魁者必膺上赏，与爻辞云“有嘉折首，获匪其丑”，如出一辙焉。按上与三相应，上为王师，敌必属三，三爻曰：“日昃之离，何可久也”，知此番行军，定卜马到功成，不数旬而戡定矣。后果未匝月，而渠丑受诛，佐贺遂平。</p>',89)])])}const m=e(i,[["render",l]]);export{b as __pageData,m as default};
